mapper.select:
select
    coalesce(sum(case when o.status = 5 then o.amount else 0 end), 0) as turnover,
    coalesce(sum(case when o.status = 5 then 1 else 0 end), 0) as valid_order_count,
    coalesce(
        sum(case when o.status = 5 then 1 else 0 end) / nullif(count(o.id), 0),
        0
    ) as order_completion_rate,
    coalesce(avg(case when o.status = 5 then o.amount end), 0) as unit_price,
    (
        select count(u.id)
        from user u
        where u.create_time >= #{begin}
          and u.create_time <= #{end}
    ) as new_users
from orders o
where o.order_time >= #{begin}
  and o.order_time <= #{end}
